import { RERAIL_DATABASE_FILE } from "../engine/storage/database.js";
import { RULES_DUMP_FILE } from "../engine/catalog/rule-bootstrap.js";
import { DAEMON_ACCESS_TOKEN_FILE, DAEMON_LOG_FILE, DAEMON_STATE_FILE } from "../runtime/daemon-control.js";

const escape = (name: string) => name.replaceAll(".", "\\.");
/** What Rerail writes in its home, from each writer's own constant, with the suffixes a write cut short leaves. */
const RERAIL_HOME_ENTRY = new RegExp(
  `^(?:${[DAEMON_STATE_FILE, DAEMON_LOG_FILE, DAEMON_ACCESS_TOKEN_FILE, RERAIL_DATABASE_FILE, RULES_DUMP_FILE].map(escape).join("|")}).*$`,
  "u",
);

/** In the Rerail home: the capability a loopback daemon keeps across restarts. */
export const DAEMON_ACCESS_TOKEN_FILE = "access-token";
export const DAEMON_STATE_FILE = "daemon.json";
export const DAEMON_LOG_FILE = "daemon.log";
const START_LOCK_DIR = "start.lock";

/**
 * Stops the daemon. It deletes daemon.json and keeps daemon.log and access-token for the next start.
 */
export function stop(): void {}
// leaves "daemon.log" and "access-token" in place

